+					}
+				}
+			} catch (InterruptedException e) {
+				// Restore interrupt, then bail out
+				Thread.currentThread().interrupt();
 			}
 		}
+	}

+	private synchronized void shutDown() {
 		if (io != null) {
 			io.disconnect();
 		}

-		connected = false;
 		userThreadPool.shutdown();
+		connected.set(false);
+		notifyAll();
 	}

 	/**
@@ -161,7 +179,7 @@ public class TS3Query {
